$ErrorActionPreference='Continue'
$r=[ordered]@{Time=(Get-Date -Format o);Computer=Get-CimInstance Win32_ComputerSystem | Select-Object Manufacturer,Model,TotalPhysicalMemory,HypervisorPresent;CPU=Get-CimInstance Win32_Processor | Select-Object Name,NumberOfCores,NumberOfLogicalProcessors,MaxClockSpeed,VirtualizationFirmwareEnabled,SecondLevelAddressTranslationExtensions;Memory=@(Get-CimInstance Win32_PhysicalMemory | Select-Object Manufacturer,PartNumber,Capacity,Speed,ConfiguredClockSpeed,DeviceLocator);OS=Get-CimInstance Win32_OperatingSystem | Select-Object Caption,BuildNumber,InstallDate,LastBootUpTime,FreePhysicalMemory;Disk=@(Get-PhysicalDisk | Select-Object FriendlyName,Size,BusType,MediaType,HealthStatus);Volumes=@(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' | Select-Object DeviceID,Size,FreeSpace);GPU=@(Get-CimInstance Win32_VideoController | Select-Object Name,DriverVersion,DriverDate);RootFiles=@(Get-ChildItem C:\ -Force -File -ErrorAction SilentlyContinue | Select-Object Name,Length);Features=@(Get-CimInstance Win32_OptionalFeature | Where-Object Name -match 'Subsystem-Linux|VirtualMachinePlatform|Hyper-V-All' | Select-Object Name,InstallState)}
$r | ConvertTo-Json -Depth 6 | Set-Content -Encoding UTF8 reports\2026-10-05\本轮硬件实测.json
$r | ConvertTo-Json -Depth 6
